# CtMetaShinyLiveApp.R
# ShinyLive (WebAssembly / webR) Replica of CtMetaShinyApp.R
# Dynamic Meta-Analysis Shiny Application: CCTA vs. Standard of Care (SOC)
#
# To export and preview as a standalone ShinyLive WebAssembly site from R:
#   # 1. Place CtMetaShinyLiveApp.R (as app.R) in an app directory and export:
#   dir.create("shinylive_app", showWarnings = FALSE)
#   file.copy("CtMetaShinyLiveApp.R", "shinylive_app/app.R", overwrite = TRUE)
#   shinylive::export(appdir = "shinylive_app", destdir = "site")
#   # 2. Serve the static site:
#   utils::browseURL("http://127.0.0.1:8081")
#   httpuv::runServer("127.0.0.1", 8081, list(
#     staticPaths = list("/" = httpuv::staticPath("site", indexhtml = TRUE))
#   ))

library(shiny)

# -------------------------------------------------------------------------
# 0. WebAssembly / WebR Compatibility Shim for 'metafor' (Missing 'Matrix')
# -------------------------------------------------------------------------
# In WebR (R 4.6 wasm), the binary 'Matrix' package is not present in the
# WebAssembly repository, which causes `library(metafor)` to fail with:
#   Error: package 'Matrix' required by 'metafor' could not be found
# When running under WebR (or if Matrix is unavailable), we provide base-R
# equivalents for the Matrix helpers used by metafor and patch metafor's
# package metadata in a writable temporary library path before loading.
if (identical(R.version$os, "emscripten") || !nzchar(system.file(package = paste0("Mat", "rix")))) {
  matrix_shims <- list(
    rankMatrix = function(x, ...) qr(as.matrix(x))$rank,
    Matrix = function(data = NA, nrow = 1, ncol = 1, byrow = FALSE, dimnames = NULL, ...) {
      matrix(data = data, nrow = nrow, ncol = ncol, byrow = byrow, dimnames = dimnames)
    },
    Diagonal = function(n, x = NULL, ...) {
      if (missing(n)) diag(x) else if (is.null(x)) diag(n) else diag(x, n, n)
    },
    bdiag = function(...) {
      mats <- list(...)
      if (length(mats) == 1L && is.list(mats[[1L]])) mats <- mats[[1L]]
      mats <- lapply(mats, as.matrix)
      nr <- sum(vapply(mats, nrow, 1L))
      nc <- sum(vapply(mats, ncol, 1L))
      out <- matrix(0, nrow = nr, ncol = nc)
      r <- 0L
      c <- 0L
      for (m in mats) {
        if (nrow(m) > 0L && ncol(m) > 0L) {
          out[(r + 1L):(r + nrow(m)), (c + 1L):(c + ncol(m))] <- m
          r <- r + nrow(m)
          c <- c + ncol(m)
        }
      }
      out
    },
    symmpart = function(x) (x + t(x)) / 2,
    nearPD = function(x, ...) {
      s <- (x + t(x)) / 2
      e <- eigen(s, symmetric = TRUE)
      e$values <- pmax(e$values, 1e-8)
      list(mat = e$vectors %*% diag(e$values, length(e$values)) %*% t(e$vectors))
    },
    sparse.model.matrix = function(object, data = environment(object), ...) {
      stats::model.matrix(object, data = data, ...)
    }
  )

  # Assign into .GlobalEnv (since shiny::as.shiny.appobj sources app.R in a child env)
  for (fn_name in names(matrix_shims)) {
    assign(fn_name, matrix_shims[[fn_name]], envir = .GlobalEnv)
  }

  mf_src <- system.file(package = "metafor")
  if (nzchar(mf_src)) {
    patch_lib <- file.path(tempdir(), "webr_patched_lib")
    dir.create(patch_lib, recursive = TRUE, showWarnings = FALSE)
    mf_dst <- file.path(patch_lib, "metafor")
    if (!dir.exists(mf_dst)) {
      file.copy(mf_src, patch_lib, recursive = TRUE)
    }
    pkg_rds <- file.path(mf_dst, "Meta", "package.rds")
    ns_rds  <- file.path(mf_dst, "Meta", "nsInfo.rds")
    if (file.exists(pkg_rds) && file.exists(ns_rds)) {
      keep_pkgs <- c("R", "methods", "stats", "utils", "graphics", "grDevices", "digest")
      pkg_meta <- readRDS(pkg_rds)
      pkg_meta$Depends <- pkg_meta$Depends[names(pkg_meta$Depends) %in% keep_pkgs]
      pkg_meta$Imports <- pkg_meta$Imports[names(pkg_meta$Imports) %in% keep_pkgs]
      pkg_meta$DESCRIPTION["Depends"] <- "R (>= 4.0.0), methods"
      pkg_meta$DESCRIPTION["Imports"] <- "stats, utils, graphics, grDevices, digest"
      saveRDS(pkg_meta, pkg_rds)

      ns_meta <- readRDS(ns_rds)
      ns_meta$imports <- ns_meta$imports[vapply(ns_meta$imports, function(x) x[1L] %in% keep_pkgs, logical(1L))]
      ns_meta$exports <- setdiff(ns_meta$exports, "ranef")
      if (!is.null(ns_meta$S3methods) && nrow(ns_meta$S3methods) > 0L) {
        ns_meta$S3methods <- ns_meta$S3methods[ns_meta$S3methods[, 1L] != "ranef", , drop = FALSE]
      }
      saveRDS(ns_meta, ns_rds)
      .libPaths(c(patch_lib, .libPaths()))
    }
  }
}

library(metafor)

if (exists("matrix_shims", inherits = FALSE)) {
  mf_imp <- parent.env(asNamespace("metafor"))
  for (fn_name in names(matrix_shims)) {
    if (!exists(fn_name, envir = mf_imp, inherits = FALSE)) {
      try(assign(fn_name, matrix_shims[[fn_name]], envir = mf_imp), silent = TRUE)
    }
  }
}

