load_meta_data <- function() {
  derived_paths <- c(
    "Meta_data_derived_22_Oct_2026.csv",
    "CtMetaShiny/Meta_data_derived_22_Oct_2026.csv"
  )
  raw_paths <- c(
    "Meta_data_22_Oct_2026_for_R.csv",
    "CtMetaShiny/Meta_data_22_Oct_2026_for_R.csv",
    "metaData_22_Oct_2026.csv",
    "CtMetaShiny/metaData_22_Oct_2026.csv"
  )

  scot0 <- NULL
  for (p in derived_paths) {
    if (file.exists(p)) {
      scot0 <- read.csv(p, stringsAsFactors = FALSE)
      break
    }
  }

  if (is.null(scot0)) {
    for (p in raw_paths) {
      if (file.exists(p)) {
        scot0 <- read.csv(p, stringsAsFactors = FALSE)
        break
      }
    }
  }

  # In ShinyLive / WebAssembly browser virtual filesystem, fall back to embedded CSV data
  if (is.null(scot0)) {
    scot0 <- read.csv(text = trimws(embedded_meta_csv), stringsAsFactors = FALSE)
  }

  # Ensure derived variables exist (matching lines 8-18 of Meta_template_22_Oct_2026.R)
  scot0$studyName <- paste0(scot0$Author, " ", scot0$Year)
  scot0$socSe     <- ifelse(scot0$SOC == "SE", 1, 0)
  scot0$socMibi   <- ifelse(scot0$SOC %in% c("Mibi", "MIBI"), 1, 0)
  scot0$socImag   <- ifelse(scot0$SOC %in% c("Mibi", "MIBI", "SE"), 1, 0)
  scot0$socExEcg  <- ifelse(scot0$SOC %in% c("ExEcg"), 1, 0)
  scot0$socStress <- ifelse(scot0$SOC %in% c("ExEcg", "Mibi", "MIBI", "SE"), 1, 0)
  scot0$fuYs      <- scot0$FuDays / 365
  scot0$fuYsLog   <- log(scot0$fuYs)
  scot0$ptYsFu    <- scot0$N * scot0$fuYs
  scot0$UA_CT.n   <- scot0$ACS_CT.n - scot0$MI_CT.n
  scot0$UA_SOC.n  <- scot0$ACS_SOC.n - scot0$MI_SOC.n
  scot0$dmDich    <- ifelse(is.na(scot0$DmPctMean), NA, ifelse(scot0$DmPctMean >= 17, 1, 0))

  # Merge Mibi and MIBI into a single category ("Mibi") and coerce SOC and Setting to factors
  scot0$SOC <- ifelse(scot0$SOC %in% c("Mibi", "MIBI"), "Mibi", as.character(scot0$SOC))
  scot0$SOC <- factor(scot0$SOC, levels = c("Clinical", "ExEcg", "Mibi", "SE"))
  scot0$Setting <- factor(scot0$Setting, levels = c("Clinic", "ED"))

  scot0
}

