# -------------------------------------------------------------------------
# 3. Server Logic
# -------------------------------------------------------------------------
server <- function(input, output, session) {

  # -----------------------------------------------------------------------
  # Overlapping SOC & Dummy Variable Checkbox Synchronization Logic
  # -----------------------------------------------------------------------
  # Base modalities:
  #   chk_clinical -> SOC == "Clinical"
  #   chk_exEcg    -> SOC == "ExEcg"   (exEcg == 1)
  #   chk_mibi     -> SOC == "Mibi"    (mibi == 1)
  #   chk_se       -> SOC == "SE"      (se == 1)
  # Composite dummies:
  #   chk_imag     -> Mibi + SE        (imag == 1)
  #   chk_stress   -> ExEcg + Mibi + SE (stress == 1)

  # When user toggles `imag`:
  observeEvent(input$chk_imag, {
    if (isTRUE(input$chk_imag)) {
      if (!isTRUE(input$chk_mibi)) updateCheckboxInput(session, "chk_mibi", value = TRUE)
      if (!isTRUE(input$chk_se))   updateCheckboxInput(session, "chk_se", value = TRUE)
      if (isTRUE(input$chk_exEcg) && !isTRUE(input$chk_stress)) {
        updateCheckboxInput(session, "chk_stress", value = TRUE)
      }
    } else {
      # Only uncheck Mibi and SE if both were currently checked (i.e. user directly unchecked `imag`)
      if (isTRUE(input$chk_mibi) && isTRUE(input$chk_se)) {
        updateCheckboxInput(session, "chk_mibi", value = FALSE)
        updateCheckboxInput(session, "chk_se", value = FALSE)
        if (isTRUE(input$chk_stress)) {
          updateCheckboxInput(session, "chk_stress", value = FALSE)
        }
      }
    }
  }, ignoreInit = TRUE)

  # When user toggles `stress`:
  observeEvent(input$chk_stress, {
    if (isTRUE(input$chk_stress)) {
      if (!isTRUE(input$chk_exEcg)) updateCheckboxInput(session, "chk_exEcg", value = TRUE)
      if (!isTRUE(input$chk_mibi))  updateCheckboxInput(session, "chk_mibi", value = TRUE)
      if (!isTRUE(input$chk_se))    updateCheckboxInput(session, "chk_se", value = TRUE)
      if (!isTRUE(input$chk_imag))  updateCheckboxInput(session, "chk_imag", value = TRUE)
    } else {
      # Only uncheck ExEcg, Mibi, SE, and imag if all three stress modalities were currently checked
      if (isTRUE(input$chk_exEcg) && isTRUE(input$chk_mibi) && isTRUE(input$chk_se)) {
        updateCheckboxInput(session, "chk_exEcg", value = FALSE)
        updateCheckboxInput(session, "chk_mibi", value = FALSE)
        updateCheckboxInput(session, "chk_se", value = FALSE)
        updateCheckboxInput(session, "chk_imag", value = FALSE)
      }
    }
  }, ignoreInit = TRUE)

  # When user toggles any constituent stress modality (ExEcg, Mibi, SE):
  observeEvent(list(input$chk_exEcg, input$chk_mibi, input$chk_se), {
    imag_should_be   <- isTRUE(input$chk_mibi) && isTRUE(input$chk_se)
    stress_should_be <- isTRUE(input$chk_exEcg) && isTRUE(input$chk_mibi) && isTRUE(input$chk_se)

    if (!identical(isTRUE(input$chk_imag), imag_should_be)) {
      updateCheckboxInput(session, "chk_imag", value = imag_should_be)
    }
    if (!identical(isTRUE(input$chk_stress), stress_should_be)) {
      updateCheckboxInput(session, "chk_stress", value = stress_should_be)
    }
  }, ignoreInit = TRUE)

  # Quick preset buttons
  observeEvent(input$btn_all_soc, {
    updateCheckboxInput(session, "chk_clinical", value = TRUE)
    updateCheckboxInput(session, "chk_exEcg", value = TRUE)
    updateCheckboxInput(session, "chk_mibi", value = TRUE)
    updateCheckboxInput(session, "chk_se", value = TRUE)
    updateCheckboxInput(session, "chk_imag", value = TRUE)
    updateCheckboxInput(session, "chk_stress", value = TRUE)
  })

  observeEvent(input$btn_clear_soc, {
    updateCheckboxInput(session, "chk_clinical", value = FALSE)
    updateCheckboxInput(session, "chk_exEcg", value = FALSE)
    updateCheckboxInput(session, "chk_mibi", value = FALSE)
    updateCheckboxInput(session, "chk_se", value = FALSE)
    updateCheckboxInput(session, "chk_imag", value = FALSE)
    updateCheckboxInput(session, "chk_stress", value = FALSE)
  })

  observeEvent(input$btn_only_imag, {
    updateCheckboxInput(session, "chk_clinical", value = FALSE)
    updateCheckboxInput(session, "chk_exEcg", value = FALSE)
    updateCheckboxInput(session, "chk_mibi", value = TRUE)
    updateCheckboxInput(session, "chk_se", value = TRUE)
    updateCheckboxInput(session, "chk_imag", value = TRUE)
    updateCheckboxInput(session, "chk_stress", value = FALSE)
  })

  observeEvent(input$btn_only_stress, {
    updateCheckboxInput(session, "chk_clinical", value = FALSE)
    updateCheckboxInput(session, "chk_exEcg", value = TRUE)
    updateCheckboxInput(session, "chk_mibi", value = TRUE)
    updateCheckboxInput(session, "chk_se", value = TRUE)
    updateCheckboxInput(session, "chk_imag", value = TRUE)
    updateCheckboxInput(session, "chk_stress", value = TRUE)
  })

  observeEvent(input$btn_only_clinical, {
    updateCheckboxInput(session, "chk_clinical", value = TRUE)
    updateCheckboxInput(session, "chk_exEcg", value = FALSE)
    updateCheckboxInput(session, "chk_mibi", value = FALSE)
    updateCheckboxInput(session, "chk_se", value = FALSE)
    updateCheckboxInput(session, "chk_imag", value = FALSE)
    updateCheckboxInput(session, "chk_stress", value = FALSE)
  })

  # -----------------------------------------------------------------------
  # Reactive Data Subsetting & Effect Size Calculation
  # -----------------------------------------------------------------------
  selected_soc_levels <- reactive({
    lvls <- character(0)
    if (isTRUE(input$chk_clinical)) lvls <- c(lvls, "Clinical")
    if (isTRUE(input$chk_exEcg))    lvls <- c(lvls, "ExEcg")
    if (isTRUE(input$chk_mibi))     lvls <- c(lvls, "Mibi")
    if (isTRUE(input$chk_se))       lvls <- c(lvls, "SE")
    lvls
  })

  # Subset of raw/derived `scot0` matching SOC and Setting filters (used for Step 5 median event rates)
  filtered_scot0 <- reactive({
    soc_lvls <- selected_soc_levels()
    if (length(soc_lvls) == 0) {
      return(scot0[0, , drop = FALSE])
    }
    keep <- as.character(scot0$SOC) %in% soc_lvls
    if (input$setting_filter != "Either") {
      keep <- keep & (as.character(scot0$Setting) == input$setting_filter)
    }
    scot0[keep, , drop = FALSE]
  })

  # Endpoint dataframe (`endpointData0` -> `complete.cases` -> `escalc`) matching Meta_template_22_Oct_2026.R
  endpoint_data <- reactive({
    df_sub <- filtered_scot0()
    if (nrow(df_sub) == 0) return(NULL)

    ep <- input$endpoint
    ct_col  <- paste0(ep, "_CT.n")
    soc_col <- paste0(ep, "_SOC.n")

    endpointData0 <- data.frame(
      study    = df_sub$studyName,
      x        = df_sub[[ct_col]],
      a        = df_sub$nCT,
      y        = df_sub[[soc_col]],
      b        = df_sub$nSoc,
      meanAge  = df_sub$AgeMean,
      meanDm   = df_sub$DmPctMean,
      meanMale = df_sub$MalePctMean,
      yr       = df_sub$Year,
      SOC      = df_sub$SOC,
      se       = df_sub$socSe,
      mibi     = df_sub$socMibi,
      imag     = df_sub$socImag,
      exEcg    = df_sub$socExEcg,
      stress   = df_sub$socStress,
      setting  = df_sub$Setting,
      smok     = df_sub$SmokingAnyHxPctMean,
      fuYs     = df_sub$fuYs,
      stringsAsFactors = FALSE
    )

    endpointData0 <- endpointData0[complete.cases(endpointData0), , drop = FALSE]
    if (nrow(endpointData0) == 0) return(NULL)

    metafor::escalc(
      measure = "RR",
      ai = x, n1i = a,
      ci = y, n2i = b,
      slab = study,
      data = endpointData0
    )
  })

  # Fit `metafor::rma(yi, vi, data = endpointData, method = "REML")`
  endpoint_res <- reactive({
    ep_dat <- endpoint_data()
    if (is.null(ep_dat) || nrow(ep_dat) < 2) return(NULL)
    tryCatch(
      metafor::rma(yi, vi, data = ep_dat, slab = study, method = "REML"),
      error = function(e) {
        # Fallback if REML does not converge on very small subsets
        tryCatch(metafor::rma(yi, vi, data = ep_dat, slab = study, method = "DL"), error = function(e2) NULL)
      }
    )
  })

  # Sidebar summary badge
  output$subset_summary_badge <- renderUI({
    soc_lvls <- selected_soc_levels()
    soc_display <- ifelse(soc_lvls == "Mibi", "MPI", soc_lvls)
    ep_dat   <- endpoint_data()
    n_k      <- if (is.null(ep_dat)) 0 else nrow(ep_dat)
    n_pts    <- if (is.null(ep_dat) || n_k == 0) 0 else sum(ep_dat$a + ep_dat$b)

    div(
      style = "background: #f4f7fa; border: 1px solid #cfd8e3; border-radius: 6px; padding: 10px 12px; font-size: 12.5px;",
      tags$strong("Active Filter Summary:"),
      tags$ul(
        style = "padding-left: 18px; margin: 6px 0 0 0;",
        tags$li(tags$b("Endpoint: "), endpoint_labels[[input$endpoint]]),
        tags$li(tags$b("SOC Included: "), if (length(soc_display) == 0) "None" else paste(soc_display, collapse = ", ")),
        tags$li(tags$b("Setting: "), input$setting_filter),
        tags$li(tags$b("Studies in Model (k): "), n_k),
        tags$li(tags$b("Total Patients: "), format(n_pts, big.mark = ","))
      )
    )
  })

  # -----------------------------------------------------------------------
  # STEP 1: metafor::rma & Exponentiated Risk Ratio (95% CI)
  # -----------------------------------------------------------------------
  output$step1_summary_ui <- renderUI({
    res <- endpoint_res()
    if (is.null(res)) {
      return(div(
        class = "flag-alert",
        "Insufficient studies (need at least 2 studies with complete data) for the selected subset."
      ))
    }

    # Following the exact instructions in Step 1:
    # Take the 4-decimal estimate & se as displayed by rma (e.g. 0.3541 and 0.1125)
    # and run exp(est + c(-1.96, 1.96) * se), then round to 3 decimals.
    est_raw <- as.numeric(res$b[1])
    se_raw  <- as.numeric(res$se[1])
    est_4   <- round(est_raw, 4)
    se_4    <- round(se_raw, 4)

    rr_est_exact <- exp(est_4)
    rr_ci_exact  <- exp(est_4 + c(-1.96, 1.96) * se_4)

    rr_formatted_3 <- sprintf("%.3f (%.3f \u2013 %.3f)", round(rr_est_exact, 3), round(rr_ci_exact[1], 3), round(rr_ci_exact[2], 3))

    pval <- as.numeric(res$pval[1])

    sig_badge <- if (pval < 0.05) {
      span(style = "background:#dcfce7; color:#166534; padding:2px 8px; border-radius:4px; font-size:12px; font-weight:700;",
           sprintf("Statistically Significant (p = %.4f)", pval))
    } else {
      span(style = "background:#f1f5f9; color:#475569; padding:2px 8px; border-radius:4px; font-size:12px; font-weight:600;",
           sprintf("Not Statistically Significant (p = %.4f)", pval))
    }

    direction_ui <- if (pval < 0.05) {
      if (rr_est_exact < 1) {
        div(style = "font-size: 12.5px; color: #1e293b; margin-top: 6px; font-weight: 600;",
            "CCTA leads to lower risk")
      } else if (rr_est_exact > 1) {
        div(style = "font-size: 12.5px; color: #1e293b; margin-top: 6px; font-weight: 600;",
            "CCTA leads to higher risk")
      } else {
        NULL
      }
    } else {
      NULL
    }

    i2_val  <- as.numeric(res$I2)
    tau2_val <- as.numeric(res$tau2)
    q_pval  <- as.numeric(res$QEp)

    het_explain_txt <- if (i2_val < 25) {
      sprintf(
        "Low heterogeneity (I\u00b2 = %.1f%%, \u03c4\u00b2 = %.4f, Q-test p = %.4f): Almost all observed variability across trials is consistent with random sampling error (chance) rather than true differences in treatment effect between studies.",
        i2_val, tau2_val, q_pval
      )
    } else if (i2_val < 50) {
      sprintf(
        "Low-to-moderate heterogeneity (I\u00b2 = %.1f%%, \u03c4\u00b2 = %.4f, Q-test p = %.4f): A modest proportion (%.1f%%) of the variability in effect estimates across trials may reflect genuine clinical or methodological differences (such as trial setting or comparator modality) rather than chance alone.",
        i2_val, tau2_val, q_pval, i2_val
      )
    } else if (i2_val < 75) {
      sprintf(
        "Moderate-to-substantial heterogeneity (I\u00b2 = %.1f%%, \u03c4\u00b2 = %.4f, Q-test p = %.4f): More than half (%.1f%%) of the variance between trials reflects true between-study differences in treatment effect rather than sampling error. Consider exploring subsets by comparator modality or trial setting.",
        i2_val, tau2_val, q_pval, i2_val
      )
    } else {
      sprintf(
        "Considerable heterogeneity (I\u00b2 = %.1f%%, \u03c4\u00b2 = %.4f, Q-test p = %.4f): Most of the variability across trials (%.1f%%) is driven by genuine between-study differences rather than random chance. The pooled Risk Ratio should be interpreted with caution alongside subgroup filters and influential study diagnostics.",
        i2_val, tau2_val, q_pval, i2_val
      )
    }

    div(
      div(
        class = "rr-highlight-box",
        div(style = "font-size: 12px; font-weight: 600; color: #1e40af; text-transform: uppercase;",
            "Risk Ratio (95%)"),
        div(class = "rr-highlight-value", rr_formatted_3),
        div(style = "margin-top: 8px;", sig_badge),
        direction_ui
      ),
      div(
        class = "nns-grid",
        div(
          class = "metric-box",
          div(class = "metric-label", "Heterogeneity"),
          div(class = "metric-val", sprintf("I² = %.1f%%", i2_val)),
          div(class = "metric-sub", sprintf("τ² = %.4f (Q p = %.4f)", tau2_val, q_pval)),
          tags$button(
            id = "btn_toggle_het_explain",
            type = "button",
            class = "btn-toggle-drawer",
            style = "margin-top: 8px; margin-bottom: 0; padding: 5px 10px; font-size: 12px;",
            onclick = "var el = document.getElementById('step1_het_explain_drawer'); if (el.style.display === 'none') { el.style.display = 'block'; this.innerHTML = '&#9650; Hide Explanation'; } else { el.style.display = 'none'; this.innerHTML = '&#9660; Explain'; }",
            HTML("&#9660; Explain")
          ),
          div(
            id = "step1_het_explain_drawer",
            style = "display: none; margin-top: 8px; padding: 8px 10px; background: #eff6ff; border-left: 3px solid #3b82f6; border-radius: 4px; font-size: 12.5px; color: #1e293b; line-height: 1.45;",
            het_explain_txt
          )
        )
      )
    )
  })

  output$step1_rma_print <- renderPrint({
    res <- endpoint_res()
    req(res)
    print(res)
  })

  # -----------------------------------------------------------------------
  # STEP 2: Forest Plot
  # -----------------------------------------------------------------------
  output$step2_forest_plot <- renderPlot({
    endpointRes <- endpoint_res()
    ep_dat      <- endpoint_data()
    validate(
      need(!is.null(endpointRes) && !is.null(ep_dat),
           "Please select a subset with at least 2 valid studies to display the forest plot.")
    )
    study <- ep_dat$study
    par(mar = c(5, 4, 2, 2))
    metafor::forest(
      endpointRes,
      refline = 0,
      xlab = "Risk Ratio",
      slab = study
    )
  }, width = 760, height = 620, res = 96)
  outputOptions(output, "step2_forest_plot", suspendWhenHidden = FALSE)

  # -----------------------------------------------------------------------
  # STEP 3: Funnel Plot for Publication Bias
  # -----------------------------------------------------------------------
  output$step3_funnel_plot <- renderPlot({
    res <- endpoint_res()
    validate(
      need(!is.null(res), "Please select a subset with at least 2 valid studies to display the funnel plot.")
    )
    par(mar = c(5, 4, 3, 2))
    metafor::funnel(
      res,
      xlab = "Log Risk Ratio",
      ylab = "Standard Error",
      main = "Funnel Plot for Publication Bias"
    )
  }, width = 560, height = 420, res = 96)
  outputOptions(output, "step3_funnel_plot", suspendWhenHidden = FALSE)

  output$step3_egger_print <- renderPrint({
    res <- endpoint_res()
    req(res)
    if (res$k >= 3) {
      cat("Egger's Regression Test for Funnel Plot Asymmetry:\n")
      print(metafor::regtest(res, model = "rma"))
    } else {
      cat("Egger's regression test requires at least 3 studies.")
    }
  })

  # -----------------------------------------------------------------------
  # STEP 4: Influential Studies — influence(endpointRes)
  # -----------------------------------------------------------------------
  influence_res <- reactive({
    res <- endpoint_res()
    if (is.null(res)) return(NULL)
    tryCatch(influence(res), error = function(e) NULL)
  })

  output$step4_influence_banner <- renderUI({
    inf <- influence_res()
    ep_dat <- endpoint_data()
    if (is.null(inf) || is.null(ep_dat)) {
      return(NULL)
    }

    is_flagged <- as.logical(inf$is.infl)
    flagged_studies <- ep_dat$study[which(is_flagged)]

    if (length(flagged_studies) > 0) {
      div(
        class = "flag-alert",
        tags$span("Flagged Influential Study/Studies (*): "),
        tags$strong(paste(flagged_studies, collapse = ", "))
      )
    } else {
      div(
        class = "no-flag-alert",
        "No single study is flagged as overly influential (*) by metafor::influence() in this subset."
      )
    }
  })

  output$step4_influence_print <- renderPrint({
    inf <- influence_res()
    req(inf)
    print(inf)
  })

  output$step4_influence_mobile_table <- renderUI({
    inf    <- influence_res()
    ep_dat <- endpoint_data()
    if (is.null(inf) || is.null(ep_dat)) {
      return(NULL)
    }

    inf_df     <- as.data.frame(inf$inf)
    is_flagged <- as.logical(inf$is.infl)

    rows_ui <- lapply(seq_len(nrow(inf_df)), function(i) {
      flagged <- isTRUE(is_flagged[i])
      tags$tr(
        class = if (flagged) "infl-row-flagged" else NULL,
        tags$td(ep_dat$study[i]),
        tags$td(sprintf("%.1f%%", inf_df$weight[i])),
        tags$td(sprintf("%.3f", inf_df$cook.d[i])),
        tags$td(sprintf("%.2f", inf_df$rstudent[i])),
        tags$td(if (flagged) "Yes (*)" else "No")
      )
    })

    div(
      class = "mobile-table-wrap",
      tags$table(
        class = "mobile-inf-table",
        tags$thead(
          tags$tr(
            tags$th("Study"),
            tags$th("Weight"),
            tags$th("Cook's D"),
            tags$th("Resid. (r)"),
            tags$th("Flagged")
          )
        ),
        tags$tbody(rows_ui)
      )
    )
  })
  outputOptions(output, "step4_influence_mobile_table", suspendWhenHidden = FALSE)

  output$step4_baujat_plot <- renderPlot({
    res <- endpoint_res()
    ep_dat <- endpoint_data()
    req(res, ep_dat)
    if (res$k >= 3) {
      par(mar = c(4.5, 4.5, 2.5, 1.5))
      b_coords <- metafor::baujat(res)
      plot(
        x = b_coords$x, y = b_coords$y,
        col = "#1e3a8a", pch = 19, cex = 0.9,
        main = "Baujat Influence Plot",
        xlab = "Squared Pearson Residual (Heterogeneity Contribution)",
        ylab = "Influence on Overall Result"
      )
      text(
        x = b_coords$x, y = b_coords$y,
        labels = ep_dat$study,
        pos = 3, cex = 0.78, col = "#0f172a"
      )
    }
  }, width = 520, height = 340, res = 96)
  outputOptions(output, "step4_baujat_plot", suspendWhenHidden = FALSE)

  # -----------------------------------------------------------------------
  # STEP 5: Number Needed to Scan (NNS), ARR/ARI & RRR/RRI (Rows 530 - 599)
  # -----------------------------------------------------------------------
  step5_metrics <- reactive({
    df_sub <- filtered_scot0()
    res    <- endpoint_res()
    if (nrow(df_sub) == 0 || is.null(res)) return(NULL)

    ep <- input$endpoint
    ct_events  <- df_sub[[paste0(ep, "_CT.n")]]
    soc_events <- df_sub[[paste0(ep, "_SOC.n")]]

    # Event risk per patient-year as calculated in Meta_template_22_Oct_2026.R (lines 534-598)
    rate_ct_vec  <- ct_events / (df_sub$nCT * df_sub$fuYs)
    rate_soc_vec <- soc_events / (df_sub$nSoc * df_sub$fuYs)

    sum_ct  <- summary(rate_ct_vec)
    sum_soc <- summary(rate_soc_vec)

    # Exact medians and 4-sig-fig medians (matching R's summary() display on lines 534-561)
    med_ct_exact  <- median(rate_ct_vec, na.rm = TRUE)
    med_soc_exact <- median(rate_soc_vec, na.rm = TRUE)

    med_ct_4  <- signif(med_ct_exact, 4)
    med_soc_4 <- signif(med_soc_exact, 4)

    # Absolute risk change per patient-year (using template's 4-sig-fig summary medians & exact medians)
    diff_4     <- med_soc_4 - med_ct_4     # > 0 means CT prevents events; < 0 means CT increases events
    diff_exact <- med_soc_exact - med_ct_exact

    abs_diff_4     <- abs(diff_4)
    abs_diff_exact <- abs(diff_exact)

    nns_4     <- if (abs_diff_4 > 0) 1 / abs_diff_4 else Inf
    nns_exact <- if (abs_diff_exact > 0) 1 / abs_diff_exact else Inf

    # Relative risk reduction / increase based on median event rates per patient-year
    rel_change_median <- if (med_soc_4 > 0) abs_diff_4 / med_soc_4 else NA_real_

    # Relative risk reduction / increase from pooled meta-analysis RR
    est_4  <- round(as.numeric(res$b[1]), 4)
    rr_est <- exp(est_4)
    rel_change_rma <- abs(1 - rr_est)

    list(
      rate_ct_vec       = rate_ct_vec,
      rate_soc_vec      = rate_soc_vec,
      sum_ct            = sum_ct,
      sum_soc           = sum_soc,
      med_ct_4          = med_ct_4,
      med_soc_4         = med_soc_4,
      med_ct_exact      = med_ct_exact,
      med_soc_exact     = med_soc_exact,
      diff_4            = diff_4,
      abs_diff_4        = abs_diff_4,
      abs_diff_exact    = abs_diff_exact,
      nns_4             = nns_4,
      nns_exact         = nns_exact,
      rel_change_median = rel_change_median,
      rr_est            = rr_est,
      rel_change_rma    = rel_change_rma,
      pval              = as.numeric(res$pval[1])
    )
  })

  output$step5_nns_ui <- renderUI({
    m <- step5_metrics()
    if (is.null(m)) {
      return(div(class = "flag-alert", "No valid studies available to compute NNS."))
    }

    is_reduction <- m$diff_4 > 0
    arr_label <- if (is_reduction) "Absolute Risk Reduction (ARR)" else "Absolute Risk Increase (ARI)"
    rrr_label <- if (is_reduction) "Relative Risk Reduction (RRR)" else "Relative Risk Increase (RRI)"
    nns_action <- if (is_reduction) "to prevent 1 event" else "to cause 1 event"

    effect_banner <- if (is_reduction) {
      div(
        style = "background:#ecfdf5; border-left:4px solid #059669; padding:10px 14px; border-radius:4px; margin-bottom:12px;",
        tags$strong(style = "color:#065f46;",
                    sprintf("Number Needed to Scan (NNS): %.1f patient-years (%s)", m$nns_4, nns_action))
      )
    } else if (m$diff_4 < 0) {
      div(
        style = "background:#fff7ed; border-left:4px solid #ea580c; padding:10px 14px; border-radius:4px; margin-bottom:12px;",
        tags$strong(style = "color:#9a3412;",
                    sprintf("Number Needed to Scan (NNS): %.1f patient-years (%s)", m$nns_4, nns_action))
      )
    } else {
      div(
        class = "flag-alert",
        "Median event rates per patient-year are identical in CCTA and SOC arms (NNS is infinite)."
      )
    }

    div(
      effect_banner,
      div(
        class = "nns-grid",
        div(
          class = "metric-box",
          div(class = "metric-label", arr_label),
          div(class = "metric-val", style = "font-size: 15px;",
              sprintf("%.3f%% per patient-year", m$abs_diff_4 * 100))
        ),
        div(
          class = "metric-box",
          div(class = "metric-label", "Median Event Risk / Patient-Year"),
          div(class = "metric-val", style = "font-size: 15px;",
              sprintf("CT: %.2f%% vs. SOC: %.2f%% per patient-year", m$med_ct_4 * 100, m$med_soc_4 * 100))
        ),
        div(
          class = "metric-box",
          div(class = "metric-label", rrr_label),
          div(class = "metric-val",
              if (is.na(m$rel_change_median)) "N/A" else sprintf("%.1f%%", m$rel_change_median * 100))
        )
      )
    )
  })

  output$step5_rates_print <- renderPrint({
    m <- step5_metrics()
    req(m)
    cat("CCTA Arm Event Risk per Patient-Year — summary(CT_events / (nCT * fuYs)):\n")
    print(m$sum_ct)
    cat("\nSOC Arm Event Risk per Patient-Year — summary(SOC_events / (nSoc * fuYs)):\n")
    print(m$sum_soc)
  })

  # -----------------------------------------------------------------------
  # Included Studies Data Table
  # -----------------------------------------------------------------------
  output$included_studies_table <- renderTable({
    ep_dat <- endpoint_data()
    req(ep_dat)
    soc_char <- as.character(ep_dat$SOC)
    soc_char <- ifelse(soc_char == "Mibi", "MPI", soc_char)
    df_out <- data.frame(
      Study        = ep_dat$study,
      SOC          = soc_char,
      Setting      = as.character(ep_dat$setting),
      CCTA_Events  = as.integer(ep_dat$x),
      CCTA_Total   = as.integer(ep_dat$a),
      SOC_Events   = as.integer(ep_dat$y),
      SOC_Total    = as.integer(ep_dat$b),
      FollowUp_Yrs = round(ep_dat$fuYs, 2),
      Log_RR_yi    = round(as.numeric(ep_dat$yi), 4),
      Var_vi       = round(as.numeric(ep_dat$vi), 4),
      RR_Study     = round(exp(as.numeric(ep_dat$yi)), 3),
      stringsAsFactors = FALSE
    )
    df_out
  }, striped = TRUE, hover = TRUE, bordered = TRUE, width = "100%")
  outputOptions(output, "included_studies_table", suspendWhenHidden = FALSE)
}

